INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 1000001, "2025/01/31 12:00:00", -416.5, "2030/01/01 14:59:59", 1, 0.0, 190801, 1, 2, 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, 3.414);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 1000002, "2025/01/31 12:00:00", -416.5, "2030/01/01 14:59:59", 2, 0.0, 190801, 1, 2, 1, "ミッションをクリアして、\n報酬をゲットしましょう！", 62, 3.099);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 1000003, "2025/01/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3, 0.0, 190801, 1, 2, 1, "受け取ることができる\n報酬があるようです\n確認してみてください", 63, 2.801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 1000004, "2025/01/31 12:00:00", -416.5, "2030/01/01 14:59:59", 4, 0.0, 190801, 1, 2, 2, "報酬がもらえますよ！\nチェックしてみてください", 63, 0.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 1000005, "2025/01/31 12:00:00", -363.0, "2030/01/01 14:59:59", 5, 0.0, 190801, 1, 1, 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, 2.12);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 1000006, "2025/01/31 12:00:00", -363.0, "2030/01/01 14:59:59", 6, 0.0, 190801, 1, 2, 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, 1.68);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 1000007, "2025/01/31 12:00:00", -363.0, "2030/01/01 14:59:59", 7, 0.0, 190801, 1, 1, 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, 2.33);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ラビリスタ", 1020101, "2025/01/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, -6.0, 133701, 10201, 7, 3, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 61, 5.18);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("クリスティーナ", 1020102, "2025/01/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, -2.0, 133901, 10201, 2, 1, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 61, 8.77);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ネネカ", 1020103, "2025/01/31 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 133801, 10201, 1, 6, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 61, 15.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ランファ", 1020201, "2025/02/28 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 134301, 10202, 5, 2, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 61, 9.061);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("チカ", 1020202, "2025/02/28 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 134401, 10202, 2, 1, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 61, 7.699);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("アオイ", 1020301, "2025/03/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 134601, 10203, 2, 1, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 61, 8.595);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("クローチェ", 1020302, "2025/03/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 134501, 10203, 2, 1, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 61, 7.758);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ルイズマリー", 1020401, "2025/04/30 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 132302, 10204, 6, 2, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 61, 7.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("イロハ", 1020402, "2025/04/30 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 132402, 10204, 2, 1, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 61, 7.904);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ソノ", 1020403, "2025/04/30 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 132502, 10204, 2, 4, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 61, 8.487);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カノン", 1020502, "2025/05/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 134901, 10205, 2, 1, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 61, 8.763);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ツムギ", 1020503, "2025/05/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 134801, 10205, 3, 1, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 61, 6.417);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("エリス", 1020601, "2025/06/30 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 135001, 10206, 7, 3, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 61, 10.335);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("シェフィ", 1020602, "2025/06/30 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 135101, 10206, 4, 2, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 61, 6.281);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("プレシア", 1020603, "2025/06/30 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 135201, 10206, 2, 1, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 61, 12.244);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("クリア", 1020701, "2025/07/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 135301, 10207, 8, 2, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 61, 6.339);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("アネモネ", 1020702, "2025/07/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 135401, 10207, 9, 7, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 61, 8.184);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("アイラ", 1020801, "2025/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 129101, 10208, 2, 9, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 61, 3.906);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("シナツ", 1020802, "2025/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 129201, 10208, 2, 1, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 61, 14.465);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ヒヨリ", 1020803, "2025/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 100101, 10208, 3, 4, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 61, 8.662);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("レイ", 1020804, "2025/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 401, 0.0, 100301, 10208, 3, 1, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 61, 10.915);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ユキノ", 1020901, "2025/09/30 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 135802, 10209, 7, 1, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 61, 6.042);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("サツキ", 1020902, "2025/09/30 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 135903, 10209, 1, 4, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 61, 9.402);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ルルィ", 1020903, "2025/09/30 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 136902, 10209, 1, 8, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 61, 8.16);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カスミ", 1021001, "2025/10/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 137401, 10210, 2, 3, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 61, 5.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("アラクネ", 1021002, "2025/10/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 136001, 10210, 1, 4, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 61, 8.12);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ナーナ", 1021003, "2025/10/31 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 136202, 10210, 2, 4, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 61, 6.386);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ユイ", 1021101, "2025/11/30 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 136402, 10211, 4, 3, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 61, 7.438);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ミソラ", 1021102, "2025/11/30 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 136302, 10211, 5, 1, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 61, 8.35);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("シズル", 1021201, "2025/12/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 136501, 10212, 2, 1, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 61, 5.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("リノ", 1021202, "2025/12/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 137902, 10212, 2, 1, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 61, 5.25);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ラビリスタ", 1021203, "2025/12/31 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 106801, 10212, 2, 1, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 61, 7.5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ライラエル", 1021301, "2026/01/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 126501, 10213, 2, 1, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 61, 8.204);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ネフィ＝ネラ", 1021302, "2026/01/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 129701, 10213, 2, 1, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 61, 7.176);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ヴァイオレット", 1021303, "2026/01/31 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 133101, 10213, 5, 1, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 61, 8.602);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ライラエル", 1021304, "2026/02/06 12:00:00", -285.0, "2030/01/01 14:59:59", 102, 0.0, 138101, 10213, 3, 1, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 61, 10.14);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ネフィ＝ネラ", 1021305, "2026/02/06 12:00:00", -285.0, "2030/01/01 14:59:59", 202, 0.0, 138201, 10213, 7, 1, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 61, 10.152);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ヴァイオレット", 1021306, "2026/02/06 12:00:00", -285.0, "2030/01/01 14:59:59", 302, 0.0, 138001, 10213, 3, 4, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 61, 9.688);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ペコリーヌ", 1021307, "2026/02/12 12:00:00", -285.0, "2030/01/01 14:59:59", 401, 0.0, 138301, 10213, 1, 2, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 61, 5.928);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ワカナ", 1021401, "2026/02/28 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 138702, 10214, 2, 4, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 61, 9.19);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("シオリ", 1021402, "2026/02/28 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 138802, 10214, 3, 1, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 61, 8.724);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("グレイス", 1021501, "2026/03/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 138902, 10215, 1, 4, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 61, 7.758);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("キョウカ", 1021502, "2026/03/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 139002, 10215, 4, 6, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 61, 6.375);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ルルィ", 1021503, "2026/03/31 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 136902, 10215, 1, 6, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 61, 6.173);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ミホ", 1021601, "2026/04/30 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 139202, 10216, 2, 6, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 61, 4.202);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("マホ", 1021602, "2026/04/30 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 139302, 10216, 1, 6, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 61, 2.842);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("エリカ", 1021603, "2026/04/30 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 139402, 10216, 1, 4, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 61, 4.598);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("リリ", 1021701, "2026/05/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 125802, 10217, 3, 4, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 61, 6.533);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("プレシア", 1021702, "2026/05/31 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 126102, 10217, 3, 3, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 61, 5.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("クリア", 1021703, "2026/05/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 126002, 10217, 4, 3, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 61, 5.214);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("リリ", 1021704, "2026/05/31 12:00:00", -285.0, "2030/01/01 14:59:59", 102, 0.0, 139501, 10217, 3, 1, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 61, 8.781);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("クリア", 1021705, "2026/05/31 12:00:00", -285.0, "2030/01/01 14:59:59", 202, 0.0, 139601, 10217, 1, 2, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 61, 6.529);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("プレシア", 1021706, "2026/05/31 12:00:00", -285.0, "2030/01/01 14:59:59", 302, 0.0, 139701, 10217, 2, 3, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 61, 3.195);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ルイズマリー", 1021801, "2026/06/30 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 139902, 10218, 3, 2, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 61, 12.43);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("クレジッタ", 1021802, "2026/06/30 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 140001, 10218, 3, 2, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 61, 6.35);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("フブキ", 1021901, "2026/07/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 140102, 10219, 5, 1, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 61, 10.23);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ヴァンピィ", 1021902, "2026/07/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 140201, 10219, 2, 1, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 61, 5.584);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("クローチェ", 1022001, "2026/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 201, 0.0, 126401, 10220, 3, 6, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 61, 2.8);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ヴルム", 1022002, "2026/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 101, 0.0, 127802, 10220, 3, 4, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 61, 8.9);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("クローチェ", 1022003, "2026/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 202, 0.0, 140602, 10220, 1, 2, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 61, 4.49);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("ヴルム", 1022004, "2026/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 102, 0.0, 140501, 10220, 3, 1, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 61, 9.42);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("リーザ", 1022005, "2026/08/31 12:00:00", -285.0, "2030/01/01 14:59:59", 301, 0.0, 140402, 10220, 1, 4, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 61, 7.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 2000001, "2026/04/10 12:00:00", -416.5, "2030/01/01 14:59:59", 1, 0.0, 190801, 2, 2, 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, 3.414);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 2000002, "2026/04/10 12:00:00", -416.5, "2030/01/01 14:59:59", 2, 0.0, 190801, 2, 2, 1, "ミッションをクリアして、\n報酬をゲットしましょう！", 62, 3.099);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 2000003, "2026/04/10 12:00:00", -416.5, "2030/01/01 14:59:59", 3, 0.0, 190801, 2, 2, 1, "受け取ることができる\n報酬があるようです\n確認してみてください", 63, 2.801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 2000004, "2026/04/10 12:00:00", -416.5, "2030/01/01 14:59:59", 4, 0.0, 190801, 2, 2, 2, "報酬がもらえますよ！\nチェックしてみてください", 63, 0.0);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 2000005, "2026/04/10 12:00:00", -363.0, "2030/01/01 14:59:59", 5, 0.0, 190801, 2, 1, 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, 2.12);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 2000006, "2026/04/10 12:00:00", -363.0, "2030/01/01 14:59:59", 6, 0.0, 190801, 2, 2, 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, 1.68);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("カリン", 2000007, "2026/04/10 12:00:00", -363.0, "2030/01/01 14:59:59", 7, 0.0, 190801, 2, 1, 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, 2.33);
